float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

float2 arcRS(float2 uv)
{
    float2 p = uv - 0.5;
    float r = length(p) * 2.0;
    float th = atan2(p.y, p.x) * 57.29578;
    th = th + step(th, -90.0) * 360.0;
    return float2(r, (165.0 - th) / 150.0);
}

float arcProfile(float sc)
{
    return pow(sc, 0.9) * (1.0 - smoothstep(0.86, 1.0, sc));
}

// kırıklı tel: yay boyunca doğrusal parçalı sapma (keskin köşeler) + ince detay
float bolt(float s, float seed)
{
    float x = s * 16.0;
    float i0 = floor(x);
    float f = frac(x);
    float a = hash21(float2(i0, seed)) - 0.5;
    float b = hash21(float2(i0 + 1.0, seed)) - 0.5;
    float fine = (vnoise(float2(s * 70.0, seed * 3.1)) - 0.5) * 0.35;
    return lerp(a, b, f) + fine;
}

code.fragment:
float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float2 a = arcRS(i.uv);
    float r = a.x;
    float s = a.y;
    float sc = saturate(s);
    float inArc = step(0.0, s) * step(s, 1.0);
    float R0 = 0.94;
    float w = _Width * arcProfile(sc);
    float frame = floor(i.time * _Rate);

    float lines = 0.0;
    float halo = 0.0;
    for (int k = 0; k < 3; k++)
    {
        float on = step(float(k) + 0.5, _Count);
        float seed = frame * 7.13 + float(k) * 31.7;
        float c = R0 - w * (0.25 + 0.3 * float(k)) + bolt(s, seed) * w * _Amp;
        float seg = step(0.35, hash21(float2(floor(s * 6.0 + float(k) * 0.37), seed)));
        float dd = abs(r - c);
        lines += on * seg * (1.0 - smoothstep(0.0, _Thick, dd));
        halo += on * seg * exp(-dd / max(_Thick * 6.0, 0.0001)) * 0.35;
    }

    float rev = saturate(life / _Reveal);
    float revealM = 1.0 - smoothstep(rev * 1.04 - 0.04, rev * 1.04, s);
    float e = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));
    float er = hash21(float2(floor(s * 10.0), frame));
    float erodeM = step(e * 1.1, er) * (1.0 - e * 0.5);
    float m = inArc * revealM * erodeM * step(0.001, w);
    float3 col = (_Color.rgb * saturate(lines) + _Halo.rgb * halo) * m * i.color.rgb;
    return float4(col, 1.0);
}
